<script setup>
import AppShell from '@/Components/AppShell.vue';import{useForm}from'@inertiajs/vue3';
defineProps({vehicleTypes:Array});const fields=[['expedition_company','Nama Perusahaan Ekspedisi'],['driver_name','Nama Driver'],['driver_phone','Nomor HP Driver'],['vehicle_plate','Nomor Polisi'],['sender_vendor','Vendor/Pengirim'],['destination','Tujuan']];const f=useForm({expedition_company:'',driver_name:'',driver_phone:'',vehicle_plate:'',vehicle_type:'',sender_vendor:'',destination:''});const send=()=>f.post('/expedition/reports',{onSuccess:()=>f.reset()});
</script>
<template><AppShell title='Pelaporan Kedatangan' subtitle='Isi data setelah kendaraan tiba di Underpass.'><form class='card p-6' @submit.prevent='send'><h2 class='mb-6 font-bold text-red-600'>AKUN EKSPEDISI · WITA</h2><div class='grid gap-5 md:grid-cols-2'><label v-for='x in fields'>{{x[1]}} *<input v-model='f[x[0]]' class='field'/><p class='err'>{{f.errors[x[0]]}}</p></label><label>Jenis Kendaraan *<select v-model='f.vehicle_type' class='field'><option value=''>Pilih kendaraan</option><option v-for='x in vehicleTypes'>{{x}}</option></select></label><label>Jam Kedatangan<input value='Otomatis dicatat sistem saat dikirim' readonly class='field bg-slate-50'/></label></div><button :disabled='f.processing' class='btn mt-7 w-full'>{{f.processing?'MENGIRIM...':'KIRIM LAPORAN KEDATANGAN'}}</button></form></AppShell></template>
